const std = @import("std");
const cairo = @import("../../wl/buffer/shm.zig").cairo;
const icons = @import("lucide_icons.zig");

// Lucide SVG icon drawing — every glyph name the shell draws resolves to a
// vendored Lucide SVG (lucide_icons.zig, generated by scripts/
// gen_lucide_icons.py). The Material Symbols font is no longer part of the
// Zig shell, so a name with no mapping draws nothing.
//
// Each SVG is rasterized once per (icon, px) through librsvg into an
// ARGB32 surface, then painted with cairo_mask_surface: the surface's
// alpha masks a solid colour source, so one cached raster serves any
// theme colour / hover alpha without re-rendering.

// librsvg bindings — same C API as icon_raster.zig, but from memory
// (`new_from_data`) instead of a file path.
const RsvgHandle = opaque {};
const RsvgRectangle = extern struct {
    x: f64,
    y: f64,
    width: f64,
    height: f64,
};
extern fn rsvg_handle_new_from_data(data: [*c]const u8, count: usize, err: ?*?*anyopaque) ?*RsvgHandle;
extern fn rsvg_handle_close(handle: ?*RsvgHandle, err: ?*?*anyopaque) c_int;
extern fn rsvg_handle_render_document(handle: ?*RsvgHandle, cr: ?*cairo.cairo_t, viewport: *const RsvgRectangle, err: ?*?*anyopaque) c_int;
extern fn g_object_unref(object: ?*anyopaque) void;

/// The Lucide name for a material glyph name, or null when unmapped
/// (callers treat unmapped names as "draw nothing").
pub fn lucideName(material: []const u8) ?[]const u8 {
    const idx = indexFor(material) orelse return null;
    return icons.map[idx].lucide;
}

/// Rasterize one SVG at `size` px into a fresh ARGB32 surface.
fn renderSvg(svg: []const u8, size: i32) ?*cairo.cairo_surface_t {
    const handle = rsvg_handle_new_from_data(svg.ptr, svg.len, null) orelse return null;
    defer g_object_unref(handle);
    _ = rsvg_handle_close(handle, null);
    const surf = cairo.cairo_image_surface_create(cairo.CAIRO_FORMAT_ARGB32, size, size);
    if (cairo.cairo_surface_status(surf) != cairo.CAIRO_STATUS_SUCCESS) {
        cairo.cairo_surface_destroy(surf);
        return null;
    }
    const cr = cairo.cairo_create(surf);
    if (cairo.cairo_status(cr) != cairo.CAIRO_STATUS_SUCCESS) {
        cairo.cairo_destroy(cr);
        cairo.cairo_surface_destroy(surf);
        return null;
    }
    defer cairo.cairo_destroy(cr);
    const vp = RsvgRectangle{
        .x = 0,
        .y = 0,
        .width = @floatFromInt(size),
        .height = @floatFromInt(size),
    };
    if (rsvg_handle_render_document(handle, cr, &vp, null) == 0) {
        cairo.cairo_surface_destroy(surf);
        return null;
    }
    return surf;
}

const Key = struct { idx: u16, px: u16 };

// App-lifetime cache: page allocator so tests never see allocations, and
// cairo owns the surfaces. Entries are small (<=128px ARGB) and bounded
// by 45 icons x the handful of sizes the UI draws.
var cache: std.AutoHashMap(Key, *cairo.cairo_surface_t) = undefined;
var cache_inited = false;

// Name -> index table. The generated map has 136 names, so a linear scan per
// draw was the largest per-icon cost; the hash lookup makes the draw path a
// few hundred nanoseconds.
var name_index: ?std.StringHashMap(u16) = null;

var raster_count: u64 = 0;
var hit_count: u64 = 0;

pub const CacheStats = struct {
    /// SVGs rasterised since start (one per icon+size).
    rasters: u64 = 0,
    /// Cached-surface hits served to draws.
    hits: u64 = 0,
};

/// Cumulative icon-cache counters, for the widget perf reports.
pub fn cacheStats() CacheStats {
    return .{ .rasters = raster_count, .hits = hit_count };
}

fn indexFor(name: []const u8) ?u16 {
    if (name_index == null) {
        var m = std.StringHashMap(u16).init(std.heap.page_allocator);
        for (icons.map, 0..) |e, i| m.put(e.material, @intCast(i)) catch {};
        name_index = m;
    }
    if (name_index.?.get(name)) |i| return i;
    // A partial map after OOM still draws correctly via the slow path.
    for (icons.map, 0..) |e, i| {
        if (std.mem.eql(u8, e.material, name)) return @intCast(i);
    }
    return null;
}

fn surfaceFor(idx: u16, px: u16) ?*cairo.cairo_surface_t {
    if (!cache_inited) {
        cache = std.AutoHashMap(Key, *cairo.cairo_surface_t).init(std.heap.page_allocator);
        cache_inited = true;
    }
    const key = Key{ .idx = idx, .px = px };
    if (cache.get(key)) |s| {
        hit_count +%= 1;
        return s;
    }
    const surf = renderSvg(icons.map[idx].svg, px) orelse return null;
    raster_count +%= 1;
    cache.put(key, surf) catch {
        cairo.cairo_surface_destroy(surf);
        return null;
    };
    return surf;
}

/// Draw the Lucide icon for `material` centred on (cx, cy) at `px`,
/// tinted (r, g, b, a), optionally mirrored vertically (the Panel row's
/// dock icon is the taskbar's upside down). Returns false when the name
/// has no Lucide mapping or rasterization failed.
pub fn draw(
    cr: ?*cairo.cairo_t,
    material: []const u8,
    cx: f64,
    cy: f64,
    px: f64,
    r: f64,
    g: f64,
    b: f64,
    a: f64,
    flip_y: bool,
) bool {
    const c = cr orelse return false;
    const idx: u16 = indexFor(material) orelse return false;
    const pxi: u16 = @intFromFloat(@round(@min(@max(px, 8.0), 128.0)));
    const surf = surfaceFor(idx, pxi) orelse return false;
    cairo.cairo_save(c);
    cairo.cairo_set_source_rgba(c, r, g, b, a);
    cairo.cairo_translate(c, cx, cy);
    if (flip_y) cairo.cairo_scale(c, 1.0, -1.0);
    const off = -@as(f64, @floatFromInt(pxi)) * 0.5;
    _ = cairo.cairo_mask_surface(c, surf, off, off);
    cairo.cairo_restore(c);
    return true;
}

test "settings-lucide: svg rasterizes and draws through cairo" {
    const t = std.testing;
    const surf = cairo.cairo_image_surface_create(cairo.CAIRO_FORMAT_ARGB32, 64, 64);
    defer cairo.cairo_surface_destroy(surf);
    const cr = cairo.cairo_create(surf);
    defer cairo.cairo_destroy(cr);

    try t.expect(draw(cr, "search", 32, 32, 18, 1, 1, 1, 1, false));
    // Cached second draw hits the same surface.
    try t.expect(draw(cr, "search", 32, 32, 18, 1, 1, 1, 1, false));
    // Flipped draw (Panel's upside-down dock icon).
    try t.expect(draw(cr, "dock_to_bottom", 32, 32, 16, 1, 1, 1, 1, true));
    // Unmapped names and null contexts refuse instead of drawing text.
    try t.expect(!draw(cr, "definitely-not-a-glyph", 32, 32, 18, 1, 1, 1, 1, false));
    try t.expect(!draw(null, "search", 32, 32, 18, 1, 1, 1, 1, false));
    try t.expect(cairo.cairo_status(cr) == cairo.CAIRO_STATUS_SUCCESS);
}
